changeSet.sql:
UPDATE theme SET layout = $J${
  "tiles": {
    "marquee":      { "col": 1,  "row": 1,  "colSpan": 3,  "rowSpan": 28, "orientation": "vertical" },
    "identity":     { "col": 5,  "row": 1,  "colSpan": 11, "rowSpan": 4 },
    "music":        { "col": 17, "row": 1,  "colSpan": 12, "rowSpan": 7 },
    "waveSwitcher": { "col": 30, "row": 1,  "colSpan": 5,  "rowSpan": 4 },
    "freshness":    { "col": 36, "row": 1,  "colSpan": 5,  "rowSpan": 4 },
    "latestDrop":   { "col": 5,  "row": 6,  "colSpan": 11, "rowSpan": 8 },
    "stats":        { "col": 30, "row": 6,  "colSpan": 11, "rowSpan": 6 },
    "today":        { "col": 17, "row": 9,  "colSpan": 12, "rowSpan": 14 },
    "photoDrops":   { "col": 30, "row": 13, "colSpan": 5,  "rowSpan": 11 },
    "ride":         { "col": 36, "row": 13, "colSpan": 5,  "rowSpan": 11 },
    "calendar":     { "col": 5,  "row": 15, "colSpan": 11, "rowSpan": 9 },
    "projects":     { "col": 5,  "row": 25, "colSpan": 11, "rowSpan": 4 },
    "social":       { "col": 17, "row": 25, "colSpan": 12, "rowSpan": 4 },
    "hero":         { "col": 30, "row": 25, "colSpan": 11, "rowSpan": 4 }
  },
  "mobileOrder": ["identity", "today", "music", "calendar", "stats", "ride", "latestDrop", "photoDrops", "projects", "social", "hero", "marquee", "freshness"]
}$J$::jsonb
WHERE key = 'wave-02';
